package com.bananalab.lite;
import android.content.Context;import dalvik.system.DexClassLoader;import java.io.*;import java.util.zip.*;import java.lang.reflect.*;
/** Real ECJ -> JVM classes -> DX -> DEX -> ART pipeline, entirely on Android. */
final class OnDeviceJava{
 static File home(Context c){return c.getDir("java-live",0);}
 static byte[] bytes(InputStream in,int max)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Archivo de compilación demasiado grande");out.write(b,0,n);}return out.toByteArray();}
 static void immutable(File file,byte[] data)throws Exception{if(file.exists())throw new IOException("El archivo de código ya existe.");try(FileOutputStream out=new FileOutputStream(file)){if(!file.setReadOnly())throw new IOException("No pude proteger el código compilado.");out.write(data);}}
 static File tool(Context c,String name)throws Exception{File f=new File(home(c),name);if(!f.exists()){try(InputStream in=c.getAssets().open("java-tools/"+name)){immutable(f,bytes(in,name.equals("android-api.jar")?12000000:5000000));}}return f;}
 static final class Build{File jar;Class<?> type;String log;}
 static Build compile(Context c,String source)throws Exception{java.util.Map<String,String> files=new java.util.LinkedHashMap<String,String>();files.put("BananaBehavior.java",source);return compileSources(c,files);}
 static Build compileSources(Context c,java.util.Map<String,String> sources)throws Exception{File compiler=tool(c,"compiler.jar"),boot=tool(c,"boot.jar"),work=new File(home(c),"build-"+java.util.UUID.randomUUID().toString());if(!work.mkdirs())throw new IOException("No pude crear el espacio de compilación.");File classes=new File(work,"classes");classes.mkdir();java.util.List<String> paths=new java.util.ArrayList<String>();for(java.util.Map.Entry<String,String> entry:sources.entrySet()){if(!entry.getKey().matches("[A-Za-z][A-Za-z0-9]*\\.java"))throw new IOException("Nombre Java inválido");File src=new File(work,entry.getKey());try(FileOutputStream out=new FileOutputStream(src)){out.write(entry.getValue().getBytes("UTF-8"));}paths.add(src.getAbsolutePath());}File opt=new File(home(c),"opt");opt.mkdirs();ClassLoader loader=new DexClassLoader(compiler.getAbsolutePath(),opt.getAbsolutePath(),null,c.getClassLoader());JavaChat.phase("Compilando el cambio en tu dispositivo…");StringWriter diagnostics=new StringWriter();PrintWriter log=new PrintWriter(diagnostics);Class<?> ecj=loader.loadClass("org.eclipse.jdt.internal.compiler.batch.Main");Object main=ecj.getConstructor(PrintWriter.class,PrintWriter.class,boolean.class).newInstance(log,log,false);java.util.List<String> options=new java.util.ArrayList<String>(java.util.Arrays.asList("-1.6","-proc:none","-encoding","UTF-8","-bootclasspath",boot.getAbsolutePath(),"-d",classes.getAbsolutePath()));options.addAll(paths);String[] args=options.toArray(new String[0]);boolean ok;try{ok=(Boolean)ecj.getMethod("compile",String[].class).invoke(main,new Object[]{args});}catch(InvocationTargetException failure){throw new IOException("ECJ: "+failure.getCause()+"\n"+diagnostics);}log.flush();if(!ok)throw new IOException("Java no compiló:\n"+diagnostics);JavaChat.phase("Preparando la versión para Android…");File dex=new File(work,"classes.dex");Class<?> arguments=loader.loadClass("com.android.dx.command.dexer.Main$Arguments");Object dxargs=arguments.newInstance();arguments.getMethod("parse",String[].class).invoke(dxargs,new Object[]{new String[]{"--output="+dex.getAbsolutePath(),"--no-strict",classes.getAbsolutePath()}});Class<?> dx=loader.loadClass("com.android.dx.command.dexer.Main");int result;try{result=(Integer)dx.getMethod("run",arguments).invoke(null,dxargs);}catch(InvocationTargetException failure){throw new IOException("DX: "+failure.getCause());}if(result!=0||!dex.isFile())throw new IOException("No se pudo convertir el bytecode Java a DEX.");File jar=new File(work,"behavior.jar");try(InputStream in=new FileInputStream(dex);FileOutputStream output=new FileOutputStream(jar)){if(!jar.setReadOnly())throw new IOException("No pude proteger el DEX.");try(ZipOutputStream zip=new ZipOutputStream(output)){zip.putNextEntry(new ZipEntry("classes.dex"));zip.write(bytes(in,1000000));zip.closeEntry();}}Build built=new Build();built.jar=jar;JavaChat.phase("Cargando y comprobando la versión nueva…");built.type=load(c,jar);built.log="ECJ compiló el .java → .class; DX produjo DEX; ART cargó la clase.\n"+diagnostics;return built;}
 static Class<?> load(Context c,File jar)throws Exception{File opt=new File(home(c),"opt");opt.mkdirs();return new DexClassLoader(jar.getAbsolutePath(),opt.getAbsolutePath(),null,c.getClassLoader()).loadClass("com.bananalab.patch.BananaBehavior");}
}
